import ctypes
import os

# Load the required libraries
try:
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
except OSError as e:
    raise RuntimeError(f"Failed to load GSL libraries: {e}")

# Define the gsl_sf_result structure
class GslSfResult(ctypes.Structure):
    _fields_ = [
        ("val", ctypes.c_double),
        ("err", ctypes.c_double)
    ]

# Define the gsl_sf_log function
# double gsl_sf_log(const double x)
gsl.gsl_sf_log.argtypes = [ctypes.c_double]
gsl.gsl_sf_log.restype = ctypes.c_double

def compute_log(x):
    """Compute the natural logarithm of a positive number using GSL."""
    if x <= 0:
        raise ValueError("Input must be a positive number.")
    return gsl.gsl_sf_log(ctypes.c_double(x))

def assert_test():
    """Run assertion tests to validate the solution."""
    # Test valid inputs
    assert abs(compute_log(1.0) - 0.0) < 1e-10, "Test case failed for input 1.0"
    assert abs(compute_log(2.718281828459045) - 1.0) < 1e-10, "Test case failed for input e"
    assert abs(compute_log(10.0) - 2.302585092994046) < 1e-10, "Test case failed for input 10.0"

    # Test invalid inputs
    try:
        compute_log(-1.0)
    except ValueError as e:
        assert str(e) == "Input must be a positive number.", "Test case failed for negative input"

    try:
        compute_log(0.0)
    except ValueError as e:
        assert str(e) == "Input must be a positive number.", "Test case failed for zero input"

if __name__ == "__main__":
    assert_test()
